BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path = public, extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data) VALUES ('74000000-0000-0000-0000-000000000001','expiry-owner@example.test',now(),'{"display_name":"Persistent owner"}');
INSERT INTO public.documents(id,owner_id,title,content) VALUES('75000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','Keep persistent','permanent');
CREATE TEMP TABLE expiry_archive_before AS SELECT * FROM legacy_archive.migration_log;

SELECT temporary_start(repeat('d',64),'demo','bob');
SELECT is((SELECT count(*)::int FROM temporary_private.documents d JOIN temporary_private.sessions s ON s.workspace_id=d.workspace_id WHERE s.token_hash=repeat('d',64)),3,'demo has exactly three fictional fixtures');
SELECT temporary_start(repeat('c',64),'demo','bob');
SELECT is((SELECT count(*)::int FROM temporary_private.documents a JOIN temporary_private.sessions sa ON sa.workspace_id=a.workspace_id JOIN temporary_private.documents b ON b.id=a.id JOIN temporary_private.sessions sb ON sb.workspace_id=b.workspace_id WHERE sa.token_hash=repeat('d',64) AND sb.token_hash=repeat('c',64)),0,'fixture ids are distinct across visitors');
SELECT temporary_end(repeat('c',64));
SELECT is((SELECT count(*)::int FROM jsonb_array_elements(temporary_list(repeat('d',64),1)) d WHERE d->'permissions'->>'role'='owner'),1,'Bob owns his meeting notes');
SELECT is((SELECT count(*)::int FROM jsonb_array_elements(temporary_list(repeat('d',64),1)) d WHERE d->'permissions'->>'role'='editor'),1,'Bob can edit Alice proposal');
SELECT is((SELECT count(*)::int FROM jsonb_array_elements(temporary_list(repeat('d',64),1)) d WHERE d->'permissions'->>'role'='viewer'),1,'Bob can view Charlie specification');
SELECT temporary_private.seed_demo(workspace_id) FROM temporary_private.sessions WHERE token_hash=repeat('d',64);
SELECT is((SELECT count(*)::int FROM temporary_private.documents d JOIN temporary_private.sessions s ON s.workspace_id=d.workspace_id WHERE s.token_hash=repeat('d',64)),3,'seeding twice is idempotent');
CREATE TEMP TABLE expiry_old_ids AS SELECT d.id FROM temporary_private.documents d JOIN temporary_private.sessions s ON s.workspace_id=d.workspace_id WHERE s.token_hash=repeat('d',64);
UPDATE temporary_private.workspaces SET reset_at=clock_timestamp() WHERE id=(SELECT workspace_id FROM temporary_private.sessions WHERE token_hash=repeat('d',64));
SELECT throws_ok($$SELECT temporary_list(repeat('d',64),1)$$,'P0001','DEMO_RESET','deadline blocks reads without cron');
SELECT throws_ok($$SELECT temporary_create(repeat('d',64),1,'{"title":"stale","content":"old"}')$$,'P0001','DEMO_RESET','deadline blocks stale create without cron');
SELECT is((temporary_session(repeat('d',64))->>'generation')::int,2,'metadata refresh resets expired generation');
SELECT is(temporary_session(repeat('d',64))->>'persona','bob','reset preserves selected persona');
SELECT is((temporary_session(repeat('d',64))->>'generation')::int,2,'duplicate refresh resets only once');
SELECT is((SELECT count(*)::int FROM temporary_private.documents WHERE id IN (SELECT id FROM expiry_old_ids)),0,'old generation ids are gone');
SELECT is((SELECT count(*)::int FROM temporary_private.history h JOIN temporary_private.documents d ON d.id=h.document_id JOIN temporary_private.sessions s ON s.workspace_id=d.workspace_id WHERE s.token_hash=repeat('d',64)),3,'reset restores one history revision per document');
SELECT throws_ok($$SELECT temporary_list(repeat('d',64),1)$$,'P0001','DEMO_RESET','stale generation denied after reset');
SELECT lives_ok($$SELECT temporary_list(repeat('d',64),2)$$,'new generation is usable');
SELECT temporary_start(repeat('e',64),'guest',NULL);
SELECT is((SELECT expires_at-created_at FROM temporary_private.sessions WHERE token_hash=repeat('e',64)),interval '5 hours','guest session starts with fixed five hour lifetime');
SELECT temporary_session(repeat('e',64));
SELECT is((SELECT expires_at-created_at FROM temporary_private.sessions WHERE token_hash=repeat('e',64)),interval '5 hours','guest activity never extends expiry');
CREATE TEMP TABLE expiry_guest_document AS SELECT (temporary_create(repeat('e',64),1,'{"title":"expire me","content":"temporary"}')->>'id')::uuid AS id;
SELECT temporary_update(repeat('e',64),1,(SELECT id FROM expiry_guest_document),'{"content":"revision","createVersion":true}');
SELECT temporary_add_attachment(repeat('e',64),1,(SELECT id FROM expiry_guest_document),'{"filename":"test.txt","mimeType":"text/plain","sizeBytes":1,"url":"/attachments/11111111-1111-1111-1111-111111111111"}');
SELECT temporary_heartbeat(repeat('e',64),1,(SELECT id FROM expiry_guest_document),'{"active":true}');
UPDATE temporary_private.workspaces SET expires_at=clock_timestamp() WHERE id=(SELECT workspace_id FROM temporary_private.sessions WHERE token_hash=repeat('e',64));
SELECT throws_ok($$SELECT temporary_list(repeat('e',64),1)$$,'P0001','SESSION_EXPIRED','guest is inaccessible at deadline before cleanup');
SELECT purge_expired_workspaces();
SELECT is((SELECT count(*)::int FROM temporary_private.sessions WHERE token_hash=repeat('e',64)),0,'cleanup physically removes expired guest');
SELECT is((SELECT count(*)::int FROM temporary_private.documents WHERE title='expire me'),0,'cleanup cascades guest documents');
SELECT is((SELECT count(*)::int FROM temporary_private.history WHERE document_id IN (SELECT id FROM expiry_guest_document)),0,'cleanup cascades guest history');
SELECT is((SELECT count(*)::int FROM temporary_private.attachments WHERE document_id IN (SELECT id FROM expiry_guest_document)),0,'cleanup cascades guest attachment metadata');
SELECT is((SELECT count(*)::int FROM temporary_private.presence WHERE document_id IN (SELECT id FROM expiry_guest_document)),0,'cleanup cascades guest presence');
SELECT is((SELECT content FROM public.documents WHERE id='75000000-0000-0000-0000-000000000001'),'permanent','persistent content survives temporary maintenance');
SELECT is((SELECT jsonb_agg(to_jsonb(l) ORDER BY migration_id) FROM legacy_archive.migration_log l),(SELECT jsonb_agg(to_jsonb(l) ORDER BY migration_id) FROM expiry_archive_before l),'archive contents are unchanged');
UPDATE temporary_private.sessions SET last_active_at=clock_timestamp()-interval '24 hours', expires_at=clock_timestamp() WHERE token_hash=repeat('d',64);
SELECT throws_ok($$SELECT temporary_session(repeat('d',64))$$,'P0001','SESSION_EXPIRED','inactive demo cannot be revived');
SELECT purge_expired_workspaces();
SELECT is((SELECT count(*)::int FROM temporary_private.sessions WHERE token_hash=repeat('d',64)),0,'inactive demo is physically removed');
SELECT is((SELECT count(*)::int FROM temporary_private.history h LEFT JOIN temporary_private.documents d ON d.id=h.document_id WHERE d.id IS NULL),0,'cleanup leaves no orphan history');
SELECT is((SELECT count(*)::int FROM cron.job WHERE jobname IN ('ai-docs-expiry-minute','ai-docs-demo-midnight')),2,'cron jobs are registered exactly once');
SELECT is((SELECT schedule FROM cron.job WHERE jobname='ai-docs-expiry-minute'),'* * * * *','cleanup runs every minute');
SELECT is((SELECT schedule FROM cron.job WHERE jobname='ai-docs-demo-midnight'),'0 16 * * *','demo reset runs at midnight PHT in UTC');
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT purge_expired_workspaces()$$,'42501',NULL,'anonymous caller cannot run cleanup');
SELECT throws_ok($$SELECT ensure_demo_generation(repeat('d',64),2)$$,'42501',NULL,'anonymous caller cannot reset generations');
RESET ROLE;
SELECT is((SELECT count(*)>0 FROM temporary_private.maintenance_runs WHERE job_name='purge'),true,'cleanup records successful execution');
SELECT temporary_start(repeat('f',64),'demo','alice');
UPDATE temporary_private.workspaces SET reset_at=clock_timestamp() WHERE id=(SELECT workspace_id FROM temporary_private.sessions WHERE token_hash=repeat('f',64));
SELECT reset_due_demos();
SELECT reset_due_demos();
SELECT is((temporary_session(repeat('f',64))->>'generation')::int,2,'duplicate scheduled resets increment generation only once');
SELECT is((SELECT count(*)::int FROM temporary_private.documents d JOIN temporary_private.sessions s ON s.workspace_id=d.workspace_id WHERE s.token_hash=repeat('f',64)),3,'scheduled reset restores exactly one fixture set');
SELECT is((SELECT count(*)>0 FROM temporary_private.maintenance_runs WHERE job_name='reset'),true,'reset records successful execution');
SELECT throws_ok($test$
 DO $body$ DECLARE doc uuid; BEGIN
  SELECT d.id INTO doc FROM temporary_private.documents d JOIN temporary_private.sessions s ON s.workspace_id=d.workspace_id WHERE s.token_hash=repeat('f',64) AND d.owner_persona='alice';
  PERFORM temporary_update(repeat('f',64),2,doc,'{"content":"late commit"}');
  UPDATE temporary_private.workspaces SET reset_at=clock_timestamp() WHERE id=(SELECT workspace_id FROM temporary_private.sessions WHERE token_hash=repeat('f',64));
  SET CONSTRAINTS temporary_private.temporary_write_deadline IMMEDIATE;
 END $body$;
$test$,'P0001','DEMO_RESET','deferred constraint rejects write made before midnight when committed after it');
SELECT is((SELECT count(*)::int FROM temporary_private.documents WHERE content='late commit'),0,'late commit rollback preserves old content');
SELECT temporary_start(repeat('a',64),'guest',NULL);
SELECT throws_ok($test$
 DO $body$ BEGIN
  PERFORM temporary_create(repeat('a',64),1,'{"title":"late guest","content":"late guest"}');
  UPDATE temporary_private.workspaces SET expires_at=clock_timestamp() WHERE id=(SELECT workspace_id FROM temporary_private.sessions WHERE token_hash=repeat('a',64));
  SET CONSTRAINTS temporary_private.temporary_write_deadline IMMEDIATE;
 END $body$;
$test$,'P0001','SESSION_EXPIRED','deferred constraint rejects guest commit crossing fixed expiry');
SELECT temporary_end(repeat('a',64));
SELECT lives_ok('SET CONSTRAINTS ALL IMMEDIATE','reset and cleanup satisfy deferred checks without bypass');
SELECT is((SELECT count(*)::int FROM temporary_private.write_checks),0,'successful commit consumes all pending deadline checks');
SELECT * FROM finish();
ROLLBACK;
